import type { GameEventDefinition, GameState, Country } from './types'

/** Helper checking if any rival living country has zero or negative treasury */
export function hasBrokeCountry(state: GameState, _player: Country): boolean {
  return state.countries.some(
    (c) => c.status === 'alive' && !c.isPlayer && c.stats.treasury <= 0,
  )
}

